script:
// TextInput (ds-metrics §16 — LabeledInputField + OTP error border): label (bodyStrong, el9) → 52pt field box (padding
// h 16, radius card, bg1Elevated, 1pt border el3 ≈ controlBorder, error → error) → hint / error text (caption), gaps 8 / 2.
// Controlled: bind `value` to screen state and assign it in on.change —
//   {"type": "TextInput", "id": "email", "props": {"label": "E-mail", "value": "=email", "error": "=emailError"},
//    "on": {"change": "email = event.value"}}
param label: string = ""
param value: string = ""
param placeholder: string = ""
param hint: string = ""
param error: string = ""
param keyboard: "text" | "email" | "number" | "phone" = "text"
param secure: bool = false
event change(value: string)
event submit(value: string)
